"""Prepare consistent 20 game-units/metre cliffs, residuals and water."""
from pathlib import Path
import json,struct,numpy as np
from scipy.ndimage import zoom,gaussian_filter,binary_dilation,binary_propagation,distance_transform_edt
ROOT=Path(__file__).resolve().parents[3];OUT=next(ROOT.glob('2_*'))/'background/map_3d';data=json.loads((ROOT/'0_research/base_layout_refs/terrain_samples.json').read_text());layers=np.array(data['cliff_layers'],float);flags=np.array(data['flags']);source=np.load(OUT/'bank_working_arrays_v026.npz');codes=source['codes'];co=source['co'];old=np.load(OUT/'bank_sculpt_v029_heights.npy')
j,i=np.indices((1025,1025),dtype=float);u=np.minimum(i/8,127.999999);v=np.minimum(j/8,127.999999);ix=u.astype(int);iy=v.astype(int);u-=ix;v-=iy;a,b,c,d=layers[iy,ix],layers[iy,ix+1],layers[iy+1,ix],layers[iy+1,ix+1];ramps=((flags[iy,ix]&16)>0)&((flags[iy,ix+1]&16)>0)&((flags[iy+1,ix]&16)>0)&((flags[iy+1,ix+1]&16)>0);u=np.where(ramps,u,np.clip((u-.5)*5+.5,0,1));v=np.where(ramps,v,np.clip((v-.5)*5+.5,0,1));level=(a*(1-u)+b*u)*(1-v)+(c*(1-u)+d*u)*v;delta=(level-10)*2.4;z=old+delta;baseline=co[:,:,2]+delta
raw=(ROOT/'0_research/base_layout_refs/war3map.w3e').read_bytes();off=13;n,=struct.unpack_from('<i',raw,off);off+=4+4*n;n,=struct.unpack_from('<i',raw,off);off+=4+4*n;w,h,ox,oy=struct.unpack_from('<iiff',raw,off);off+=16;ground=np.empty((129,129));water=np.empty_like(ground);wet=np.zeros_like(ground,dtype=bool)
for y in range(h):
 for x in range(w):
  g,wa,fl,variation,cliff=struct.unpack_from('<HHBBB',raw,off+7*(y*w+x));ground[y,x]=((g-8192)/4+(cliff%16-10)*128)/20;water[y,x]=((wa%16384-8192)/4-89.6-1024)/20;wet[y,x]=bool(fl&64) and ground[y,x]<water[y,x]
levels,counts=np.unique(water[wet],return_counts=True);waterlevel=float(levels[np.argmax(counts)]);nearest=distance_transform_edt(~wet,return_distances=False,return_indices=True);waterfine=zoom(water[tuple(nearest)],1025/129,order=0);walk=(codes&1)!=0;hx=walk[:,1:]&walk[:,:-1];hy=walk[1:]&walk[:-1];limx=np.maximum(np.abs(baseline[:,1:]-baseline[:,:-1]),.56);limy=np.maximum(np.abs(baseline[1:]-baseline[:-1]),.56)
for iteration in range(24):
 correction=np.zeros((129,129));correction[wet]=np.minimum(water[wet]-.24-z[::8,::8][wet],0);z+=gaussian_filter(zoom(correction,1025/129,order=1),.65)
 for _ in range(12):
  diff=z[:,1:]-z[:,:-1];ex=np.maximum(np.abs(diff)-limx,0)*np.sign(diff)*hx;z[:,1:]-=ex*.24;z[:,:-1]+=ex*.24
  diff=z[1:]-z[:-1];ex=np.maximum(np.abs(diff)-limy,0)*np.sign(diff)*hy;z[1:]-=ex*.24;z[:-1]+=ex*.24
missing=int(np.count_nonzero(z[::8,::8][wet]>=water[wet]));assert missing==0,missing
enabled=(flags&64)>0;cells=enabled[:-1,:-1]|enabled[1:,:-1]|enabled[:-1,1:]|enabled[1:,1:];watermask=np.repeat(np.repeat(cells,8,0),8,1);low=z<waterfine+.05;lowcells=low[:-1,:-1]|low[1:,:-1]|low[:-1,1:]|low[1:,1:];connected=binary_propagation(watermask&lowcells,mask=lowcells&binary_dilation(watermask,iterations=16));finalmask=watermask|connected
excess=max(float(np.max((np.abs(z[:,1:]-z[:,:-1])-limx)[hx])),float(np.max((np.abs(z[1:]-z[:-1])-limy)[hy])));assert excess<.01,excess
np.savez_compressed(OUT/'metric_terrain_v032.npz',heights=z.astype(np.float32),water_cells=finalmask,water_mean_heights=waterfine.astype(np.float32))
report={'source':'environment_v031.blend','status':'prepared_author_trial_not_accepted','format_reference':'https://github.com/stijnherfst/HiveWE/wiki/war3map.w3e-Terrain','game_units_per_m':20,'old_cliff_step_m':4,'new_cliff_step_m':6.4,'mean_water_level_m':waterlevel,'source_water_levels_m':dict(zip(map(str,levels),map(int,counts))),'water_height_method':'Nearest source submerged vertex; disconnected raised pools retain their original level instead of sharing the river plane','original_submerged_vertices':int(wet.sum()),'source_wet_missing_after_correction':missing,'adjacent_walk_grade_excess_m':excess,'maximum_height_change_m':float(np.abs(z-old).max()),'added_connected_water_cells':int((finalmask&~watermask).sum()),'water_extension_rule':'Only connected underwater cells within 12.8m of source enabled cells; source cells retained','xy_navigation_flags_unchanged':True,'remaining':['Reground scenery and anchors','Visual cliff/bank inspection','Navigation sampling after assembly','Independent review']};(OUT/'metric_terrain_v032_prepare.json').write_text(json.dumps(report,indent=2),encoding='utf-8');print(json.dumps(report))
